import type { HighlighterCore, ThemedTokenWithVariants } from 'shiki/core'

export const codeLanguages = [
  'text',
  'javascript',
  'jsx',
  'typescript',
  'tsx',
  'json',
  'css',
  'html',
  'markdown',
  'bash',
  'yaml',
  'sql',
  'python',
] as const
export type CodeLanguage = (typeof codeLanguages)[number]
const loaders = {
  javascript: () => import('shiki/langs/javascript.mjs'),
  jsx: () => import('shiki/langs/jsx.mjs'),
  typescript: () => import('shiki/langs/typescript.mjs'),
  tsx: () => import('shiki/langs/tsx.mjs'),
  json: () => import('shiki/langs/json.mjs'),
  css: () => import('shiki/langs/css.mjs'),
  html: () => import('shiki/langs/html.mjs'),
  markdown: () => import('shiki/langs/markdown.mjs'),
  bash: () => import('shiki/langs/bash.mjs'),
  yaml: () => import('shiki/langs/yaml.mjs'),
  sql: () => import('shiki/langs/sql.mjs'),
  python: () => import('shiki/langs/python.mjs'),
}
let highlighter: Promise<HighlighterCore> | undefined
const loading = new Map<string, Promise<void>>()
/** Loads the JavaScript regex engine, two themes, and only the requested grammar on demand. */
export async function highlightCode(
  code: string,
  language: CodeLanguage,
): Promise<ThemedTokenWithVariants[][]> {
  if (language === 'text')
    return code
      .split('\n')
      .map((content) => [{ content, offset: 0, variants: { light: {}, dark: {} } }])
  if (!codeLanguages.includes(language)) throw new Error(`Unsupported language: ${language}`)
  highlighter ??= Promise.all([
    import('shiki/core'),
    import('shiki/engine/javascript'),
    import('shiki/themes/github-light.mjs'),
    import('shiki/themes/github-dark.mjs'),
  ])
    .then(([core, engine, light, dark]) =>
      core.createHighlighterCore({
        themes: [light.default, dark.default],
        langs: [],
        engine: engine.createJavaScriptRegexEngine({ forgiving: true }),
      }),
    )
    .catch((error) => {
      highlighter = undefined
      throw error
    })
  const instance = await highlighter
  if (!loading.has(language))
    loading.set(
      language,
      loaders[language]()
        .then((grammar) => instance.loadLanguage(grammar.default))
        .catch((error) => {
          loading.delete(language)
          throw error
        }),
    )
  await loading.get(language)
  return instance.codeToTokensWithThemes(code, {
    lang: language,
    themes: { light: 'github-light', dark: 'github-dark' },
  })
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

