import * as React from 'react'
import { useControllableState } from '@/components/ui/util'

/** Runs the latest cancellable action without publishing stale results after unmount. */
export function useAsyncAction() {
  const active = React.useRef<AbortController | null>(null)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState('')
  React.useEffect(
    () => () => {
      active.current?.abort()
      active.current = null
    },
    [],
  )
  const cancel = React.useCallback(() => {
    active.current?.abort()
    active.current = null
    setBusy(false)
  }, [])
  const run = React.useCallback(async <T>(task: (signal: AbortSignal) => T | Promise<T>) => {
    active.current?.abort()
    const controller = new AbortController()
    active.current = controller
    setBusy(true)
    setError('')
    try {
      const value = await task(controller.signal)
      if (!controller.signal.aborted && active.current === controller) return value
    } catch (failure) {
      if (!controller.signal.aborted && active.current === controller)
        setError(failure instanceof Error ? failure.message : 'The action failed.')
    } finally {
      if (active.current === controller) {
        active.current = null
        setBusy(false)
      }
    }
    return undefined
  }, [])
  return { busy, error, run, cancel, clearError: () => setError('') }
}

/** Bounded immutable history for controlled or uncontrolled editors. */
export function useEditorHistory<T>({
  value,
  defaultValue,
  onChange,
  limit = 50,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
  limit?: number
}) {
  const [current, setCurrent] = useControllableState({ value, defaultValue, onChange })
  const [past, setPast] = React.useState<T[]>([])
  const [future, setFuture] = React.useState<T[]>([])
  const expected = React.useRef(current)
  React.useEffect(() => {
    if (value !== undefined && value !== expected.current) {
      expected.current = value
      setPast([])
      setFuture([])
    }
  }, [value])
  const apply = (next: T) => {
    expected.current = next
    setCurrent(next)
  }
  return {
    value: current,
    canUndo: past.length > 0,
    canRedo: future.length > 0,
    commit(next: T) {
      if (Object.is(next, current)) return
      setPast((previous) => [...previous, current].slice(-Math.max(1, Math.min(100, limit))))
      setFuture([])
      apply(next)
    },
    undo() {
      if (!past.length) return
      setPast(past.slice(0, -1))
      setFuture([current, ...future])
      apply(past[past.length - 1])
    },
    redo() {
      if (!future.length) return
      setPast([...past, current])
      setFuture(future.slice(1))
      apply(future[0])
    },
  }
}

/** Accepts explicit web/blob/image URLs and relative paths, never executable protocols. */
export function productURL(value: string, image = false): string | undefined {
  const clean = value.trim()
  if (
    !clean ||
    [...clean].some((character) => character.charCodeAt(0) <= 32 || character.charCodeAt(0) === 127)
  )
    return
  if (image && /^data:image\/(?:png|jpeg|webp|gif);base64,[\da-z+/=]+$/i.test(clean)) return clean
  try {
    const url = new URL(clean, 'https://ergon.invalid/')
    if (['http:', 'https:'].includes(url.protocol) || (image && url.protocol === 'blob:'))
      return clean
  } catch {
    /* Invalid input remains inert. */
  }
}
export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
/** Creates client-side entity IDs in secure and plain-HTTP browser contexts. */
export const productId = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  const bytes = globalThis.crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6] & 15) | 64
  bytes[8] = (bytes[8] & 63) | 128
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

import * as React from 'react'

export interface TextStreamOptions {
  /** Reveal incoming text progressively, or display each received chunk immediately. */
  textAnimation?: 'typewriter' | 'none'
  /** Graphemes revealed per second, from 1 to 1,000. Defaults to 60. */
  charactersPerSecond?: number
}

/** Keeps network chunks separate from presentation. Completed history is displayed immediately. */
export function useTextStream(
  content: string,
  {
    streaming = false,
    textAnimation = 'typewriter',
    charactersPerSecond = 60,
    streamKey,
    immediate = false,
  }: TextStreamOptions & {
    streaming?: boolean
    streamKey?: string | number
    immediate?: boolean
  } = {},
) {
  // Older engines without grapheme segmentation fall back to immediate, intact text.
  const enabled =
    textAnimation === 'typewriter' && !immediate && typeof Intl.Segmenter === 'function'
  const boundaries = React.useMemo(() => {
    const offsets = [0]
    if (!enabled) return content ? [0, content.length] : offsets
    // Segment once per received chunk, never once per animation frame.
    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' })
    for (const part of segmenter.segment(content)) offsets.push(part.index + part.segment.length)
    return offsets
  }, [content, enabled])
  const length = boundaries.length - 1
  const [state, setState] = React.useState(() => ({
    content,
    streamKey,
    enabled,
    streaming,
    index: enabled && streaming ? 0 : length,
    session: enabled && streaming,
    epoch: 0,
  }))
  if (
    state.content !== content ||
    state.streamKey !== streamKey ||
    state.enabled !== enabled ||
    state.streaming !== streaming
  ) {
    const reset = state.streamKey !== streamKey || !content.startsWith(state.content)
    const session = enabled && (streaming || (!reset && state.session))
    const index = session && state.enabled ? (reset ? 0 : Math.min(state.index, length)) : length
    setState({
      content,
      streamKey,
      enabled,
      streaming,
      index,
      session: session && (streaming || index < length),
      epoch: reset ? state.epoch + 1 : state.epoch,
    })
  }
  const latest = React.useRef({ length, streaming })
  React.useLayoutEffect(() => {
    latest.current = { length, streaming }
  })
  const pending = enabled && state.session && state.index < length
  const rate = Number.isFinite(charactersPerSecond)
    ? Math.min(1000, Math.max(1, charactersPerSecond))
    : 60
  React.useEffect(() => {
    if (!pending) return
    let previous = performance.now(),
      credit = 0
    const timer = setInterval(() => {
      const now = performance.now()
      credit += ((now - previous) * rate) / 1000
      previous = now
      const count = Math.floor(credit)
      if (!count) return
      credit -= count
      setState((current) => {
        const index = Math.min(latest.current.length, current.index + count)
        return {
          ...current,
          index,
          session: latest.current.streaming || index < latest.current.length,
        }
      })
    }, 16)
    return () => clearInterval(timer)
  }, [pending, rate, state.epoch])
  return {
    text:
      enabled && state.session
        ? content.slice(0, boundaries[Math.min(state.index, length)])
        : content,
    isRevealing: pending,
  }
}
